#include <bits/stdc++.h>
using namespace std;
// BFS over (cell, left used, right used), both capped at n*m.
int main() { int n, m, r, c; long long x, y; cin >> n >> m >> r >> c >> x >> y; r--, c--; vector<string> g(n); for (auto& s : g) cin >> s; int cap = n * m; int X = min<long long>(x, cap), Y = min<long long>(y, cap); vector<vector<vector<vector<bool>>>> seen(n, vector<vector<vector<bool>>>(m, vector<vector<bool>>(X + 1, vector<bool>(Y + 1, false)))); vector<vector<bool>> ok(n, vector<bool>(m, false)); queue<array<int,4>> q; q.push({r, c, 0, 0}); seen[r][c][0][0] = true; while (!q.empty()) { auto [i, j, L, R] = q.front(); q.pop(); ok[i][j] = true; int di[] = {-1, 1, 0, 0}, dj[] = {0, 0, -1, 1}; for (int k = 0; k < 4; k++) { int a = i + di[k], b = j + dj[k], nl = L + (k == 2), nr = R + (k == 3); if (a < 0 || a >= n || b < 0 || b >= m || g[a][b] == '*' || nl > X || nr > Y || seen[a][b][nl][nr]) continue; seen[a][b][nl][nr] = true; q.push({a, b, nl, nr}); } } int cnt = 0; for (auto& row : ok) for (bool v : row) cnt += v; cout << cnt << "\n"; }
